"""NCC descriptors are independent of the optional C/C++ CMake exporter."""
import hashlib,json,os,re,time,zipfile
from pathlib import Path
from .preferences import atomic_json

ROOT_CMAKE='# Created by Zénit. This file belongs to your project.\ncmake_minimum_required(VERSION 3.20)\nproject(zenit_native LANGUAGES NONE)\ninclude("${{CMAKE_CURRENT_LIST_DIR}}/{include}")\n'

def retire_legacy_cmake(ws,root):
    """Archive an untouched auto-generated root; preserve mixed/user projects."""
    path=root/'CMakeLists.txt'
    if not path.is_file():return []
    include=Path(os.path.relpath(ws.root/'.lumen/native/targets.cmake',root)).as_posix()
    relative=path.relative_to(ws.root).as_posix();ws.resolve(relative)
    raw=path.read_bytes()
    try:unchanged=raw.decode('utf-8-sig').replace('\r\n','\n')==ROOT_CMAKE.format(include=include)
    except UnicodeError:return []
    if not unchanged:return []
    index=ws.resolve('.lumen/native/targets.json',must_exist=False)
    if not index.is_file() or index.stat().st_size>100000:return []
    try:entries=json.loads(index.read_text('utf-8'))
    except (ValueError,UnicodeError):return []
    if not isinstance(entries,dict) or not entries or len(entries)>512:return []
    for name,value in entries.items():
        if not re.fullmatch(r'[A-Za-z0-9_]{1,60}',name) or value!='.lumen/native/'+name+'/CMakeLists.txt':return []
        cmake=ws.resolve(value)
        if not cmake.is_file() or cmake.stat().st_size>100000:return []
        try:text=cmake.read_text('utf-8')
        except UnicodeError:return []
        if not text.startswith('# Generated by Zénit from the current compiler configuration.\n') or 'build-native' not in text:return []
    # The archive is written first. No original source, header or custom CMake is removed.
    archive=ws.private_dir('migrations')/('ncc-cmake-'+str(time.time_ns())+'.zip')
    with zipfile.ZipFile(archive,'x',compression=zipfile.ZIP_DEFLATED) as output:output.writestr(relative,raw)
    if path.read_bytes()!=raw:raise ValueError('CMakeLists.txt cambió durante la migración; se conserva.')
    path.unlink()
    return [{'path':relative,'backup':archive.relative_to(ws.root).as_posix(),'sha256':hashlib.sha256(raw).hexdigest()}]

def prepare_nc_project(ws,file,target,commands,folder,info):
    created=[];root=info['root'];manifest=root/'ncc.package.json'
    if not manifest.exists():
        name=re.sub(r'[^A-Za-z0-9_-]','_',file.stem)[:48] or 'application'
        data={'schema':'ncc.package.v1','package':{'name':name,'version':'0.1.0','language':'nC','edition':'2026'},
              'targets':{'main':file.relative_to(root).as_posix(),'artifact_root':'.ncc','bin':'.ncc/bin'},'dependencies':[],
              'build':{'cc':'nC.win64' if os.name=='nt' else 'native','cpu':'native','emit':['nm','obj','exe','run-manifest'],'profile':'release-fast'}}
        # Exclusive creation also preserves a manifest created concurrently.
        try:
            with manifest.open('x',encoding='utf-8',newline='\n') as stream:json.dump(data,stream,indent=2,ensure_ascii=False);stream.write('\n')
            created.append(manifest.relative_to(ws.root).as_posix())
        except FileExistsError:pass
    export=folder/'project';export.mkdir(parents=True,exist_ok=True)
    descriptor=export/'ncc-build.json'
    data={'schema':'zenit.ncc-build.v1','compiler':'ncc','source':file.relative_to(ws.root).as_posix(),
          'manifest':manifest.relative_to(ws.root).as_posix(),'target':str(target),'commands':[list(row) for row in commands]}
    try:previous=json.loads(descriptor.read_text('utf-8'))
    except (OSError,ValueError,UnicodeError):previous=None
    if previous!=data:atomic_json(descriptor,data)
    retired=retire_legacy_cmake(ws,root)
    return {'created':created,'header':None,'headerKind':None,'cmake':None,'cmakeProject':None,
            'exportedProject':export.relative_to(ws.root).as_posix(),'descriptor':descriptor.relative_to(ws.root).as_posix(),
            'manifest':[manifest.relative_to(ws.root).as_posix()],'target':target.relative_to(ws.root).as_posix(),
            'retired':retired}
